#!/usr/bin/env bash
# Generates the compiler output shown in the thesis from the examples, so it
# never has to be copied by hand.
#
#   ./generate.sh            writes generated/
#   ./generate.sh DIR        writes DIR/ instead (used by check.sh to detect
#                            outdated files in generated/)
#
# Each generated file starts with a header recording its source, compiler
# version and command. The thesis reads the part between the THESIS-SNIPPET
# markers.
set -euo pipefail

cd "$(dirname "$0")"
out=${1:-generated}
mkdir -p "$out"
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

# -fno-asynchronous-unwind-tables: no .cfi_* unwinding directives
# -fcf-protection=none:            no `endbr64`, which Ubuntu's gcc adds to
#                                  every function by default
gcc_flags=(-std=c99 -O2 -masm=intel -fno-asynchronous-unwind-tables -fcf-protection=none)
rustc_flags=(--edition 2024 -O -C codegen-units=1 -C llvm-args=-x86-asm-syntax=intel)

# output name                    compiler  source file                          function
targets=(
	"null_check_after_dereference  gcc       c/null_check_after_dereference.c     foo"
	"null_check_before_dereference gcc       c/null_check_before_dereference.c    foo"
	"aliasing_foo                  rustc     rust/src/bin/aliasing.rs             aliasing_foo"
	"non_aliasing_foo              rustc     rust/src/bin/aliasing.rs             non_aliasing_foo"
)

# Prints one function from an assembly file: its label, its instructions and
# its local jump labels (.L3:), without assembler directives or comments.
# Instructions are indented with a tab and their mnemonic padded to 8
# characters, so operands line up.
extract_function() {
	local file=$1 function=$2
	awk -v fn="$function" '
		$0 == fn ":" { inside = 1; print; next }
		!inside { next }
		/^\.Lfunc_end/ || /^[ \t]*\.(size|cfi_endproc)/ { exit }   # end of function
		/^[A-Za-z_][A-Za-z0-9_.$]*:/ { exit }                        # next function
		/^\.L[A-Za-z0-9_]+:/ { sub(/[ \t]*#.*/, ""); print; next }   # local label
		/^[ \t]*(\.|#|$)/ { next }                                   # directive, comment, blank
		{
			sub(/[ \t]*#.*/, "")
			sub(/^[ \t]+/, "")
			mnemonic = $1
			operands = substr($0, length(mnemonic) + 1)
			sub(/^[ \t]+/, "", operands)
			if (operands == "") printf "\t%s\n", mnemonic
			else printf "\t%-8s%s\n", mnemonic, operands
		}
	' "$file"
}

for target in "${targets[@]}"; do
	read -r name compiler source function <<< "$target"
	asm="$tmp/$name.s"
	case $compiler in
		gcc)
			command=(gcc "${gcc_flags[@]}" -S "$source" -o "$asm")
			version=$(gcc --version | head -n 1)
			;;
		rustc)
			command=(rustc "${rustc_flags[@]}" --emit asm "$source" -o "$asm")
			version=$(rustc --version)
			;;
		*)
			echo "unknown compiler '$compiler' for $name" >&2
			exit 1
			;;
	esac
	"${command[@]}" 2> "$tmp/stderr" || { cat "$tmp/stderr" >&2; exit 1; }

	body=$(extract_function "$asm" "$function")
	if [ -z "$body" ]; then
		echo "function '$function' not found in the assembly of $source" >&2
		exit 1
	fi

	# Show the command as it can be rerun by hand, with a placeholder output.
	shown=("${command[@]}")
	shown[${#shown[@]}-1]="$name.s"
	{
		echo "# Generated by thesis/examples/generate.sh. Do not edit by hand."
		echo "# Source:   $source, function $function"
		echo "# Compiler: $version"
		echo "# Command:  ${shown[*]}"
		echo "# THESIS-SNIPPET: assembly"
		echo "$body"
		echo "# THESIS-SNIPPET-END: assembly"
	} > "$out/$name.s"
	echo "generated $out/$name.s"
done

# ---------------------------------------------------------------------------
# Terminal sessions
# ---------------------------------------------------------------------------
# A session copies one example into an empty directory under a short name
# (main.c, main.rs) and really runs the given commands there, in the C locale
# so messages use plain ASCII quotes. The transcript shows each command after
# a `$`, followed by everything it printed.
#
# Some output differs per run or per system. Each such part is described by an
# extended regular expression (no `|`), recorded between slashes in the file's
# header; check.sh removes matches before comparing, while the thesis still
# shows the value of a real run.
#
# Each command is prefixed with its role, `compile:` or `run:`. The transcript
# has a snippet per role, so a figure can show only the step it is about, and
# a `terminal` snippet around the whole session:
#   name: "compile"   the compile command and its output (errors, warnings)
#   name: "run"       running the program and its output
#   name: "terminal"  both

# When a program is killed by a signal, bash reports that as
# "bash: line 1: PID Aborted   (core dumped) CMD". Rewrite it to what an
# interactive shell shows: "Aborted (core dumped)".
report_signals() {
	local cmd=$1 line rest
	while IFS= read -r line; do
		if [[ $line =~ ^(/usr)?(/bin/)?bash:\ line\ [0-9]+:\ +[0-9]+\ +(.*)$ ]]; then
			rest=${BASH_REMATCH[3]}
			rest=${rest%" $cmd"}
			echo "$rest" | tr -s ' '
		else
			echo "$line"
		fi
	done
}

# terminal_session NAME SOURCE COPY-AS [VARYING-REGEX...] -- ROLE: COMMAND...
terminal_session() {
	local name=$1 source=$2 copy_as=$3
	shift 3
	local varies=()
	while [ "$1" != "--" ]; do
		varies+=("$1")
		shift
	done
	shift

	local dir="$tmp/session-$name"
	mkdir -p "$dir"
	cp "$source" "$dir/$copy_as"

	local compiler=${1#*: }
	compiler=${compiler%% *}
	local version
	case $compiler in
		gcc) version=$(gcc --version | head -n 1) ;;
		rustc) version=$(rustc --version) ;;
		*) version="(none)" ;;
	esac

	{
		echo "# Generated by thesis/examples/generate.sh. Do not edit by hand."
		echo "# Source:   $source, copied to an empty directory as $copy_as"
		echo "# Compiler: $version"
		for regex in "${varies[@]}"; do
			echo "# Varies per run or system, ignored by check.sh: /$regex/"
		done
		echo "# THESIS-SNIPPET: terminal"
		local step role cmd open=""
		for step in "$@"; do
			role=${step%%: *}
			cmd=${step#*: }
			case $role in
				compile | run) ;;
				*) echo "error: '$step' does not start with 'compile: ' or 'run: '" >&2; exit 1 ;;
			esac
			# Consecutive commands with the same role share one snippet.
			if [ "$role" != "$open" ]; then
				[ -n "$open" ] && echo "# THESIS-SNIPPET-END: $open"
				echo "# THESIS-SNIPPET: $role"
				open=$role
			fi
			echo "\$ $cmd"
			# `; true` makes bash run the command as a child process, so it
			# reports a death by signal (like a double free's abort).
			(cd "$dir" && LC_ALL=C bash -c "$cmd; true" 2>&1) | report_signals "$cmd"
		done
		[ -n "$open" ] && echo "# THESIS-SNIPPET-END: $open"
		echo "# THESIS-SNIPPET-END: terminal"
	} > "$out/$name.txt"
	echo "generated $out/$name.txt"
}

terminal_session out_of_bounds_c c/out_of_bounds.c main.c \
	'^-?[0-9]+$' -- \
	"compile: gcc -std=c99 -O0 -Wall main.c -o main" \
	"run: ./main 4"

terminal_session out_of_bounds_rust rust/src/bin/out_of_bounds.rs main.rs \
	" \([0-9]+\)" -- \
	"compile: rustc --edition 2024 main.rs -o main" \
	"run: ./main 4"

terminal_session double_free_c c/double_free.c main.c \
	" \(core dumped\)" -- \
	"compile: gcc -std=c99 -O0 -Wall main.c -o main" \
	"run: ./main"

# Short error format: the point is that compilation fails; the thesis text
# explains why.
terminal_session double_free_rust rust/compile-fail/double_free.rs main.rs -- \
	"compile: rustc --edition 2024 --error-format=short main.rs -o main"

# ---------------------------------------------------------------------------
# Rewriter examples
# ---------------------------------------------------------------------------
# An example is a small project under rewriter/, in the shape of a C2Rust
# translation. A copy goes through the same steps as the benchmarks in
# pipeline/: Crown's preprocessing and analysis, then the rewriter's analysis
# and rewrite. The rewritten project must still build.
#
# The thesis shows the input straight from rewriter/, and the rewritten version
# of the same file from the output file, as the snippet `output`. The rewriter
# does not format the code it inserts, so the output is formatted with rustfmt,
# using the example's own rustfmt.toml. The input must already be formatted
# that way, so both sides of a figure look alike.

root=$(cd ../.. && pwd)
crown_dir=$root/tools/crown
rewriter=$root/tools/rewriter/target/release/rewriter

rewriter_example() {
	local name=$1 file=$2
	local project="$tmp/rewrite-$name"
	local log="$tmp/rewrite-$name.log"

	if [ ! -x "$crown_dir/target/release/crown" ] || [ ! -x "$rewriter" ]; then
		echo "Crown or the rewriter is not built; run pipeline/0_setup.sh first" >&2
		exit 1
	fi

	if ! (cd "rewriter/$name" && rustfmt --edition 2018 --check "$file") > "$log" 2>&1; then
		cat "$log" >&2
		echo "rewriter/$name/$file is not formatted; run rustfmt --edition 2018 $file there" >&2
		exit 1
	fi

	cp -r "rewriter/$name" "$project"
	rm -rf "$project/target" "$project/analysis_results"

	# Crown's scripts take the toolchain of the directory they run in, so
	# they must run from tools/crown (see pipeline/1_crown.sh).
	if ! {
		(cd "$project" && cargo build --offline) &&
		(cd "$crown_dir" && ./preprocess.sh "$project" && ./analyse.sh "$project") &&
		"$rewriter" analyze one "$project" &&
		"$rewriter" rewrite one "$project" &&
		(cd "$project" && cargo build --offline)
	} > "$log" 2>&1; then
		cat "$log" >&2
		echo "rewriting rewriter/$name failed" >&2
		exit 1
	fi
	# The example's rustfmt.toml is copied along, so it applies here as well.
	(cd "$project" && rustfmt --edition 2018 "$file")

	{
		echo "// Generated by thesis/examples/generate.sh. Do not edit by hand."
		echo "// Source:   rewriter/$name/$file, after the rewrite"
		echo "// Tools:    Crown and the rewriter in tools/, formatted with $(rustfmt --version) and rewriter/$name/rustfmt.toml"
		echo "// THESIS-SNIPPET: output"
		cat "$project/$file"
		echo "// THESIS-SNIPPET-END: output"
	} > "$out/$name.rs"
	echo "generated $out/$name.rs"
}

rewriter_example allocation_rerouting src/main.rs
